import{l as e}from"./headers-j0QAsRga.js";import"./navigation.react-server-pHORrvjv.js";import{env as t}from"cloudflare:workers";var n=`oai-authenticated-user-id`,r=`oai-authenticated-user-email`,i=`oai-authenticated-user-full-name`,a=`oai-authenticated-user-full-name-encoding`,o=`percent-encoded-utf-8`;async function s(){let t=await e(),s=t.get(n),l=t.get(r);if(!s||!l)return null;let u=t.get(i),d=u&&t.get(a)===o?c(u):null;return{userId:s,displayName:d??l,email:l,fullName:d}}function c(e){try{return decodeURIComponent(e)}catch{return null}}function l(){if(!t.DB)throw Error(`Penyimpanan belum tersedia. Coba lagi nanti.`);return t.DB}function u(){if(!t.BUCKET)throw Error(`Penyimpanan berkas belum tersedia.`);return t.BUCKET}async function d(){let e=await s(),n=(t.TEACHER_EMAILS||``).split(`,`).map(e=>e.trim().toLowerCase()).filter(Boolean);return{user:e,teacher:!!e&&n.includes(e.email.toLowerCase())}}function f(e,t=200){return Response.json(e,{status:t,headers:{"Cache-Control":`no-store`}})}function p(e){let t=e.headers.get(`origin`);return!t||t===new URL(e.url).origin}function m(e,t=2e3){return typeof e==`string`?e.trim().slice(0,t):``}function h(e){return console.error(`Parametra request failed`,e instanceof Error?e.message:`Unknown error`),f({error:`Data belum berhasil diproses. Isian tetap tersedia; silakan coba kembali.`},503)}var g=[{id:8,order:1,stage:`intro`,title:`Pengenalan Fusion`,subtitle:`Antarmuka, navigasi, satuan & membaca jobsheet`,meeting:`Tahap 1 · Persiapan`,goal:`Menyiapkan ruang kerja Fusion dan memahami urutan praktik.`,deliverable:`Desain latihan tersimpan, satuan diperiksa, dan rencana kerja singkat.`,concept:`Parametric modeling menggunakan dimensi, constraint, dan hubungan fitur. Website mendampingi praktik; pembuatan sketch, part, dan assembly tetap dilakukan di Autodesk Fusion pada komputer.`,dimensions:`Dimensi, satuan, toleransi, dan nama berkas mengikuti PDF asli. Ukuran yang belum tercantum perlu dikonfirmasi kepada guru; jangan menebak dari gambar di layar.`,steps:[{title:`Kenali ruang kerja`,instruction:`Buka workspace Design. Temukan Browser, toolbar, canvas, ViewCube, dan timeline. Latih memilih objek, zoom, pan, orbit, serta mengubah tampak.`,check:`Saya dapat mengenali area kerja dan mengatur tampilan.`,hints:[`Browser menampilkan struktur desain.`,`ViewCube membantu memilih tampak standar.`,`Latih navigasi tanpa mengubah geometri.`]},{title:`Atur satuan & simpan`,instruction:`Buat desain latihan. Periksa Document Settings dan satuan sesuai jobsheet. Simpan dengan nama yang jelas dan pastikan lokasi penyimpanannya diketahui.`,check:`Desain latihan tersimpan dengan satuan yang sesuai.`,hints:[`Satuan memengaruhi ukuran.`,`Gunakan nama sesuai arahan guru.`,`Periksa status simpan sebelum menutup desain.`]},{title:`Baca jobsheet`,instruction:`Buka pustaka jobsheet. Identifikasi judul, tampak, penampang, satuan, ukuran, serta hasil yang diminta. Catat ukuran yang belum jelas untuk ditanyakan.`,check:`Saya dapat menjelaskan target dan ukuran acuan tugas.`,hints:[`Mulai dari nama dan fungsi benda.`,`Bedakan diameter, radius, panjang, dan kedalaman.`,`Rencanakan: baca gambar → buat → ukur → simpan.`]},{title:`Rencanakan urutan praktik`,instruction:`Ikuti pengenalan Fusion, sketch 2D, membuat part 3D, kemudian assembly. Kerjakan jobsheet bernomor secara berurutan pada setiap tahap. Siapkan catatan kendala dan refleksi.`,check:`Saya siap memulai jobsheet sketch 2D nomor 1.`,hints:[`Sketch mendefinisikan profil.`,`Part memberi volume pada rancangan.`,`Periksa ukuran part sebelum merakit.`]}],quiz:[{q:`Urutan belajar yang digunakan adalah …`,options:[`Assembly → part → sketch`,`Pengenalan Fusion → sketch 2D → part 3D → assembly`,`Part → pengenalan → assembly`],answer:1,why:`Pembelajaran dimulai dari dasar menuju rakitan.`},{q:`Jika suatu ukuran tidak tercantum, tindakan yang tepat adalah …`,options:[`Menebak dari gambar`,`Mengubah satuan sembarang`,`Mengonfirmasi kepada guru`],answer:2,why:`Ukuran tidak boleh diciptakan dari tampilan visual.`},{q:`Timeline digunakan untuk …`,options:[`Meninjau urutan fitur desain`,`Mengunggah PDF`,`Mengubah nama kelas`],answer:0,why:`Timeline membantu meninjau dan merevisi riwayat pemodelan.`}]},{id:9,order:2,stage:`sketch`,title:`Sketch 2D`,subtitle:`Jobsheet 1–2 · Plat Sambungan & V Block`,meeting:`Tahap 2 · Sketch`,goal:`Membuat profil 2D sesuai acuan dengan dimensi dan constraint yang tepat.`,deliverable:`Dua desain sketch sesuai jobsheet, bukti pemeriksaan, dan refleksi.`,concept:`Dimension menetapkan ukuran, sedangkan constraint mengatur hubungan dan posisi geometri. Profil tertutup dan fully constrained adalah dua pemeriksaan berbeda; periksa keduanya sesuai jobsheet.`,dimensions:`Dimensi, satuan, toleransi, dan nama berkas mengikuti PDF asli. Ukuran yang belum tercantum perlu dikonfirmasi kepada guru; jangan menebak dari gambar di layar.`,steps:[{title:`Jobsheet 1 · Plat Sambungan`,instruction:`Buka PDF Plat Sambungan. Atur satuan mm dan bidang sketch. Bentuk kontur, lubang, slot, chamfer, serta lengkung sesuai acuan. Lengkapi dimensi dan constraint, periksa profil tertutup dan fully constrained, lalu simpan sesuai jobsheet.`,check:`Sketch Plat Sambungan sudah diperiksa dan disimpan.`,hints:[`Tandai ukuran pada gambar sebelum mulai.`,`Gunakan origin dan garis konstruksi; periksa celah dan hubungan geometri.`,`Uji apakah sketch masih bergeser. Lengkapi constraint tanpa menggandakan aturan.`]},{title:`Jobsheet 2 · V Block`,instruction:`Buka PDF V Block. Buat sumbu tegak melalui origin, gambar setengah kontur, alur V dan takik sesuai acuan. Gunakan Mirror, lengkapi dimensi serta constraint, periksa profil tertutup, lalu simpan sesuai jobsheet.`,check:`Sketch V Block sudah diperiksa dan disimpan.`,hints:[`Tandai ukuran pada gambar sebelum mulai.`,`Gunakan origin dan garis konstruksi; periksa celah dan hubungan geometri.`,`Uji apakah sketch masih bergeser. Lengkapi constraint tanpa menggandakan aturan.`]}],quiz:[{q:`Fully constrained berarti …`,options:[`Sketsa sudah diberi warna`,`Ukuran dan posisi sketsa sudah terdefinisi`,`Sketsa pasti sudah menjadi solid`],answer:1,why:`Constraint dan dimensi mengendalikan kebebasan gerak sketsa.`},{q:`Mirror memerlukan …`,options:[`Garis cermin yang tepat`,`File STL`,`Joint assembly`],answer:0,why:`Mirror mencerminkan geometri terhadap garis acuan.`},{q:`Profil tertutup diperiksa dengan …`,options:[`Mengganti warna`,`Membesarkan ukuran file`,`Memastikan tidak ada celah dan area profil dapat dikenali`],answer:2,why:`Celah dapat menghalangi pembentukan profil.`}]},{id:10,order:3,stage:`part`,title:`Membuat part 3D`,subtitle:`Jobsheet 1–6 · Dari Plat Sambungan hingga Bottle`,meeting:`Tahap 3 · Part`,goal:`Membentuk part 3D dari acuan, memilih fitur sesuai bentuk, dan memeriksa ukuran.`,deliverable:`Hasil jobsheet 1–6 dalam file sumber Fusion sesuai arahan guru; mesh opsional untuk pratinjau.`,concept:`Extrude memberi kedalaman pada profil; Revolve memutar profil terhadap sumbu. Pilih fitur berdasarkan bentuk dan penampang. Periksa lubang dan detail tepi setelah bentuk utama selesai.`,dimensions:`Dimensi, satuan, toleransi, dan nama berkas mengikuti PDF asli. Ukuran yang belum tercantum perlu dikonfirmasi kepada guru; jangan menebak dari gambar di layar. PDF Part 3D nomor 1 dan 2 masih berisi instruksi sketch 2D; pembentukan 3D perlu arahan ukuran dari guru.`,steps:[{title:`Jobsheet 1 · Plat Sambungan`,instruction:`Buka PDF Plat Sambungan. PDF ini masih latihan sketch 2D. Selesaikan sketsa, lalu minta arahan guru tentang ketebalan, kedalaman, dan fitur pembentukan 3D sebelum melanjutkan. Periksa ukuran dengan Measure dan periksa timeline. Simpan sumber Fusion; ekspor STL/OBJ hanya untuk pratinjau mesh.`,check:`Part Plat Sambungan sesuai arahan guru, diperiksa, dan disimpan.`,hints:[`Tentukan profil utama dan arah pembentukan; jangan menebak ukuran.`,`Pilih Extrude atau Revolve bila sesuai rancangan. Periksa operasi Join, Cut, atau New Body.`,`Periksa ukuran utama, lubang, dan detail tepi. Perbaiki fitur paling awal yang bermasalah.`]},{title:`Jobsheet 2 · V Block`,instruction:`Buka PDF V Block. PDF ini masih latihan sketch 2D. Selesaikan sketsa, lalu minta arahan guru tentang ketebalan, kedalaman, dan fitur pembentukan 3D sebelum melanjutkan. Periksa ukuran dengan Measure dan periksa timeline. Simpan sumber Fusion; ekspor STL/OBJ hanya untuk pratinjau mesh.`,check:`Part V Block sesuai arahan guru, diperiksa, dan disimpan.`,hints:[`Tentukan profil utama dan arah pembentukan; jangan menebak ukuran.`,`Pilih Extrude atau Revolve bila sesuai rancangan. Periksa operasi Join, Cut, atau New Body.`,`Periksa ukuran utama, lubang, dan detail tepi. Perbaiki fitur paling awal yang bermasalah.`]},{title:`Jobsheet 3 · Dudukan Poros`,instruction:`Buka PDF Dudukan Poros. Baca tampak dan penampang. Susun urutan fitur dari bentuk utama hingga detail, lalu buat part sesuai gambar. Periksa ukuran dengan Measure dan periksa timeline. Simpan sumber Fusion; ekspor STL/OBJ hanya untuk pratinjau mesh.`,check:`Part Dudukan Poros sesuai arahan guru, diperiksa, dan disimpan.`,hints:[`Tentukan profil utama dan arah pembentukan; jangan menebak ukuran.`,`Pilih Extrude atau Revolve bila sesuai rancangan. Periksa operasi Join, Cut, atau New Body.`,`Periksa ukuran utama, lubang, dan detail tepi. Perbaiki fitur paling awal yang bermasalah.`]},{title:`Jobsheet 4 · Pulley`,instruction:`Buka PDF Pulley. Baca tampak dan penampang. Susun urutan fitur dari bentuk utama hingga detail, lalu buat part sesuai gambar. Periksa ukuran dengan Measure dan periksa timeline. Simpan sumber Fusion; ekspor STL/OBJ hanya untuk pratinjau mesh.`,check:`Part Pulley sesuai arahan guru, diperiksa, dan disimpan.`,hints:[`Tentukan profil utama dan arah pembentukan; jangan menebak ukuran.`,`Pilih Extrude atau Revolve bila sesuai rancangan. Periksa operasi Join, Cut, atau New Body.`,`Periksa ukuran utama, lubang, dan detail tepi. Perbaiki fitur paling awal yang bermasalah.`]},{title:`Jobsheet 5 · Flange Pipa`,instruction:`Buka PDF Flange Pipa. Baca tampak dan penampang. Susun urutan fitur dari bentuk utama hingga detail, lalu buat part sesuai gambar. Periksa ukuran dengan Measure dan periksa timeline. Simpan sumber Fusion; ekspor STL/OBJ hanya untuk pratinjau mesh.`,check:`Part Flange Pipa sesuai arahan guru, diperiksa, dan disimpan.`,hints:[`Tentukan profil utama dan arah pembentukan; jangan menebak ukuran.`,`Pilih Extrude atau Revolve bila sesuai rancangan. Periksa operasi Join, Cut, atau New Body.`,`Periksa ukuran utama, lubang, dan detail tepi. Perbaiki fitur paling awal yang bermasalah.`]},{title:`Jobsheet 6 · Bottle`,instruction:`Buka PDF Bottle. Baca tampak dan penampang. Susun urutan fitur dari bentuk utama hingga detail, lalu buat part sesuai gambar. Periksa ukuran dengan Measure dan periksa timeline. Simpan sumber Fusion; ekspor STL/OBJ hanya untuk pratinjau mesh.`,check:`Part Bottle sesuai arahan guru, diperiksa, dan disimpan.`,hints:[`Tentukan profil utama dan arah pembentukan; jangan menebak ukuran.`,`Pilih Extrude atau Revolve bila sesuai rancangan. Periksa operasi Join, Cut, atau New Body.`,`Periksa ukuran utama, lubang, dan detail tepi. Perbaiki fitur paling awal yang bermasalah.`]}],quiz:[{q:`Extrude digunakan untuk …`,options:[`Memberi kedalaman pada profil`,`Mengunci komponen assembly`,`Membuka PDF`],answer:0,why:`Extrude membentuk atau memotong volume sepanjang arah tertentu.`},{q:`Revolve membutuhkan …`,options:[`Dua PDF`,`Profil dan sumbu putar`,`Warna material`],answer:1,why:`Profil diputar terhadap sumbu yang dipilih.`},{q:`STL menyimpan …`,options:[`Seluruh timeline Fusion`,`Semua constraint sketch`,`Geometri mesh, bukan riwayat parametrik lengkap`],answer:2,why:`Tetap simpan sumber Fusion selain ekspor mesh.`}]},{id:11,order:4,stage:`assembly`,title:`Assembly piston`,subtitle:`Jobsheet 1–5 · Komponen, rakitan & pemeriksaan gerak`,meeting:`Tahap 4 · Assembly`,goal:`Merakit komponen piston sesuai gambar acuan dan menguji hubungan geraknya.`,deliverable:`Desain assembly, file komponen, bukti pemeriksaan, dan refleksi proses.`,concept:`Component memiliki identitas dan konteks gerak dalam assembly. Joint menentukan hubungan antarkomponen; Move saja tidak mendefinisikan mekanisme. Gunakan hubungan putar, geser, atau tetap sesuai fungsi dan arahan guru.`,dimensions:`Dimensi, satuan, toleransi, dan nama berkas mengikuti PDF asli. Ukuran yang belum tercantum perlu dikonfirmasi kepada guru; jangan menebak dari gambar di layar.`,steps:[{title:`Jobsheet 1 · Cylinder Block`,instruction:`Buka PDF Cylinder Block. Buat atau periksa komponen dengan dimensi pada gambar. Beri nama sesuai daftar komponen, lalu simpan. Siapkan sebagai Component dalam assembly, bukan hanya body tanpa identitas.`,check:`Komponen Cylinder Block siap dirakit dan dimensinya diperiksa.`,hints:[`Baca semua tampak dan penampang; identifikasi bagian yang berpasangan.`,`Periksa lubang, poros, ketebalan, dan satuan. Jangan mengubah dimensi untuk memaksa pasangan.`,`Rapikan Browser, aktifkan komponen yang tepat, beri nama, dan simpan.`]},{title:`Jobsheet 2 · Piston Head`,instruction:`Buka PDF Piston Head. Buat atau periksa komponen dengan dimensi pada gambar. Beri nama sesuai daftar komponen, lalu simpan. Siapkan sebagai Component dalam assembly, bukan hanya body tanpa identitas.`,check:`Komponen Piston Head siap dirakit dan dimensinya diperiksa.`,hints:[`Baca semua tampak dan penampang; identifikasi bagian yang berpasangan.`,`Periksa lubang, poros, ketebalan, dan satuan. Jangan mengubah dimensi untuk memaksa pasangan.`,`Rapikan Browser, aktifkan komponen yang tepat, beri nama, dan simpan.`]},{title:`Jobsheet 3 · Pin Piston`,instruction:`Buka PDF Pin Piston. Buat atau periksa komponen dengan dimensi pada gambar. Beri nama sesuai daftar komponen, lalu simpan. Siapkan sebagai Component dalam assembly, bukan hanya body tanpa identitas.`,check:`Komponen Pin Piston siap dirakit dan dimensinya diperiksa.`,hints:[`Baca semua tampak dan penampang; identifikasi bagian yang berpasangan.`,`Periksa lubang, poros, ketebalan, dan satuan. Jangan mengubah dimensi untuk memaksa pasangan.`,`Rapikan Browser, aktifkan komponen yang tepat, beri nama, dan simpan.`]},{title:`Jobsheet 4 · Connecting Rod`,instruction:`Buka PDF Connecting Rod. Buat atau periksa komponen dengan dimensi pada gambar. Beri nama sesuai daftar komponen, lalu simpan. Siapkan sebagai Component dalam assembly, bukan hanya body tanpa identitas.`,check:`Komponen Connecting Rod siap dirakit dan dimensinya diperiksa.`,hints:[`Baca semua tampak dan penampang; identifikasi bagian yang berpasangan.`,`Periksa lubang, poros, ketebalan, dan satuan. Jangan mengubah dimensi untuk memaksa pasangan.`,`Rapikan Browser, aktifkan komponen yang tepat, beri nama, dan simpan.`]},{title:`Jobsheet 5 · Crankshaft`,instruction:`Buka PDF Crankshaft. Buat atau periksa komponen dengan dimensi pada gambar. Beri nama sesuai daftar komponen, lalu simpan. Siapkan sebagai Component dalam assembly, bukan hanya body tanpa identitas.`,check:`Komponen Crankshaft siap dirakit dan dimensinya diperiksa.`,hints:[`Baca semua tampak dan penampang; identifikasi bagian yang berpasangan.`,`Periksa lubang, poros, ketebalan, dan satuan. Jangan mengubah dimensi untuk memaksa pasangan.`,`Rapikan Browser, aktifkan komponen yang tepat, beri nama, dan simpan.`]},{title:`Rakit mengacu gambar lengkap`,instruction:`Buka PDF Full dan Isometris. Cocokkan Cylinder Block, Piston Head, Pin Piston, Connecting Rod, serta Crankshaft dengan daftar komponen. Tetapkan komponen acuan tetap dan hubungkan komponen dengan joint sesuai fungsi.`,check:`Struktur dan pasangan komponen sesuai gambar rakitan.`,hints:[`Pastikan seluruh komponen telah diperiksa.`,`Identifikasi bagian tetap, berputar, dan bergerak translasi.`,`Periksa pusat, sumbu, orientasi, dan derajat kebebasan setiap hubungan.`]},{title:`Uji, dokumentasikan & refleksikan`,instruction:`Amati video piston sebagai referensi gerak. Uji assembly sendiri di Fusion; periksa arah gerak dan interference pada beberapa posisi. Catat masalah, revisi dari desain sumber, lalu simpan dan kumpulkan bukti hasil.`,check:`Rakitan diuji dan hasil serta kendala dicatat.`,hints:[`Video bukan bukti bahwa desainmu bebas tabrakan.`,`Periksa beberapa posisi sepanjang gerak.`,`Simpan sumber, bukti sebelum–sesudah revisi, dan refleksi spesifik.`]}],quiz:[{q:`Move saja sudah mendefinisikan mekanisme?`,options:[`Ya, jika bentuk menempel`,`Tidak; perlu hubungan joint yang sesuai`,`Ya, jika warna sama`],answer:1,why:`Posisi visual berbeda dengan hubungan mekanis.`},{q:`Agar komponen acuan tetap tidak ikut bergerak, gunakan …`,options:[`Ground sesuai konteks rakitan`,`Zoom`,`Fillet`],answer:0,why:`Ground menetapkan komponen sebagai acuan tetap.`},{q:`Animasi lancar membuktikan bebas interference?`,options:[`Selalu`,`Jika diputar cepat`,`Tidak; tetap perlu pemeriksaan pada beberapa posisi`],answer:2,why:`Pratinjau gerak tidak menggantikan pemeriksaan geometri.`}]}];function _(e){return g.find(t=>t.id===e)}function v(e,t){try{let n=new URL(e);return n.protocol!==`https:`||n.username||n.password||t===`drive`&&n.hostname!==`drive.google.com`||t===`fusion`&&!(n.hostname===`autodesk360.com`||n.hostname.endsWith(`.autodesk360.com`)||n.hostname===`a360.co`)?``:n.href}catch{return``}}export{l as a,f as c,m as i,p as l,v as n,h as o,u as r,d as s,_ as t};